const BAD_ESCAPE = /~(?![01])/

export function getPointer(value, pointer) {
  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string')
  if (pointer === '') return value
  if (pointer[0] !== '/') throw new SyntaxError(`invalid pointer: ${pointer}`)

  let current = value
  for (const raw of pointer.slice(1).split('/')) {
    if (BAD_ESCAPE.test(raw)) throw new SyntaxError(`invalid escape in token: ${raw}`)
    const token = raw.replaceAll('~1', '/').replaceAll('~0', '~')
    if (Array.isArray(current)) {
      if (!INDEX.test(token)) throw new TypeError(`invalid array index: ${token}`)
      const index = Number(token)
      if (index >= current.length || !own(current, token)) {
        throw new RangeError(`index out of range: ${token}`)
      }
      current = current[index]
    } else if (own(current, token)) {
      current = current[token]
    } else {
      throw new ReferenceError(`missing key: ${token}`)
    }
  }
  return current
}
